-- The FINE-BEAM code key (Code keys -> Drilling -> FINE-BEAM), from the ISCAR
-- e-catalog's FINE-BEAM families; kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.finebeam', $ck${"title": "FINE-BEAM code key – deep drills and inserts", "subtitle": "High feed single and double tube drills (25 – 89 mm) with NPHT peripheral and NPMT internal / central indexable inserts", "example": "DSD-EF 25.00-26.40-FB", "decoder": "fine-beam", "sections": [{"key": "t-family", "title": "Drill – system", "sample": "DSD", "rows": [{"code": "DSD", "meaning": "Single tube (BTA) drill"}, {"code": "DDD", "meaning": "Double tube (ejector) drill"}]}, {"key": "t-connection", "title": "Drill – thread connection", "sample": "EF", "rows": [{"code": "EF", "meaning": "External 4-start thread connection, high feed"}, {"code": "IF", "meaning": "Internal single-start thread connection"}]}, {"key": "t-dia", "title": "Drill – diameter range", "rows": [{"code": "##.##-##.##", "meaning": "Diameter range in mm"}]}, {"key": "t-line", "title": "Drill – line", "rows": [{"code": "FB", "meaning": "FINE-BEAM (NPHT / NPMT inserts)"}]}, {"key": "i-family", "title": "Insert – family", "sample": "NPHT", "rows": [{"code": "NPHT", "meaning": "Peripheral precision inserts with 2 cutting edges"}, {"code": "NPMT", "meaning": "Internal and central inserts with 2 cutting edges"}]}, {"key": "i-size", "title": "Insert – size", "rows": [{"code": "##", "meaning": "Insert size"}]}, {"key": "i-thick", "title": "Insert – thickness", "rows": [{"code": "##", "meaning": "Insert thickness code"}]}, {"key": "i-radius", "title": "Insert – corner radius", "rows": [{"code": "##", "meaning": "Corner radius x10"}]}, {"key": "i-hand", "title": "Insert – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "i-chip", "title": "Insert – chipformer", "rows": [{"code": "G", "meaning": "G chipformer (general) (inferred)"}, {"code": "HF", "meaning": "High feed chipformer (inferred)"}]}, {"key": "i-position", "title": "Insert – position", "rows": [{"code": "P", "meaning": "Peripheral"}, {"code": "I", "meaning": "Internal"}, {"code": "C", "meaning": "Central"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
